mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM as rn FROM ( SELECT cc.COLLECTION_ID, cc.COLLECTION_NO, cc.COLLECTION_PERIOD, cc.COST_CENTER_ID, ccc.CENTER_NAME as COST_CENTER_NAME, cc.COLLECTION_TYPE, CASE cc.COLLECTION_TYPE WHEN 1 THEN '直接成本' WHEN 2 THEN '间接成本' WHEN 3 THEN '制造费用' ELSE '未知' END as COLLECTION_TYPE_NAME, cc.COLLECTION_AMOUNT, cc.COLLECTION_STATUS, CASE cc.COLLECTION_STATUS WHEN 1 THEN '待归集' WHEN 2 THEN '归集中' WHEN 3 THEN '已归集' WHEN 4 THEN '已审核' ELSE '未知' END as COLLECTION_STATUS_NAME, cc.COLLECTION_METHOD, CASE cc.COLLECTION_METHOD WHEN 1 THEN '手工归集' WHEN 2 THEN '自动归集' ELSE '未知' END as COLLECTION_METHOD_NAME, TO_CHAR(cc.COLLECTION_DATE, 'YYYY-MM-DD') as COLLECTION_DATE, cc.AUDITOR_ID, cc.AUDITOR_NAME, cc.AUDIT_TIME, cc.AUDIT_REMARK, cc.BOOK_ID, cc.TENANT_ID, cc.REMARK, cc.CREATE_TIME, cc.UPDATE_TIME, cc.CREATOR, cc.UPDATER FROM "REDACTED"."T_COST_COLLECTION" cc LEFT JOIN "REDACTED"."T_COST_CENTER" ccc ON cc.COST_CENTER_ID = ccc.CENTER_ID WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{bookId}
AND cc.TENANT_ID = #{tenantId}
AND cc.COLLECTION_PERIOD = #{collectionPeriod}
AND cc.COST_CENTER_ID = #{costCenterId}
AND cc.COLLECTION_TYPE = #{collectionType}
AND cc.COLLECTION_STATUS = #{collectionStatus}
AND cc.COLLECTION_NO LIKE '%' || #{collectionNo} || '%'
ORDER BY cc.COLLECTION_PERIOD DESC, cc.CREATE_TIME DESC ) a WHERE ROWNUM <= (#{offset} + #{limit}) ) WHERE rn > #{offset}

SELECT COUNT(1)
FROM "REDACTED"."T_COST_COLLECTION" cc
WHERE cc.IS_DELETED = 0

    AND cc.BOOK_ID = #{bookId}


    AND cc.TENANT_ID = #{tenantId}


    AND cc.COLLECTION_PERIOD = #{collectionPeriod}


    AND cc.COST_CENTER_ID = #{costCenterId}


    AND cc.COLLECTION_TYPE = #{collectionType}


    AND cc.COLLECTION_STATUS = #{collectionStatus}


    AND cc.COLLECTION_NO LIKE '%' || #{collectionNo} || '%'

mapper.update:
UPDATE T_COST_COLLECTION SET IS_DELETED = 1, UPDATE_TIME = SYSDATE, UPDATER = #{updaterId}, VERSION = VERSION + 1 WHERE COLLECTION_ID IN
#{id}
AND IS_DELETED = 0

UPDATE T_COST_COLLECTION SET COLLECTION_STATUS = #{collectionStatus}, AUDITOR_ID = #{auditorId}, AUDITOR_NAME = #{auditorName}, AUDIT_TIME = #{auditTime}, AUDIT_REMARK = #{auditRemark}, UPDATE_TIME = SYSDATE, UPDATER = #{updaterId}, VERSION = VERSION + 1 WHERE COLLECTION_ID IN
#{id}
AND IS_DELETED = 0

mapper.select:
SELECT SUM(CASE WHEN cc.COLLECTION_TYPE = 1 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as DIRECT_COST, SUM(CASE WHEN cc.COLLECTION_TYPE = 2 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as INDIRECT_COST, SUM(CASE WHEN cc.COLLECTION_TYPE = 3 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as MANUFACTURING_COST, SUM(cc.COLLECTION_AMOUNT) as TOTAL_COST, COUNT(CASE WHEN TO_CHAR(cc.CREATE_TIME, 'YYYY-MM') = #{period} THEN 1 ELSE NULL END) as MONTHLY_COLLECTION_COUNT, SUM(CASE WHEN TO_CHAR(cc.CREATE_TIME, 'YYYY-MM') = #{period} THEN cc.COLLECTION_AMOUNT ELSE 0 END) as MONTHLY_COLLECTION_AMOUNT, COUNT(CASE WHEN cc.COLLECTION_STATUS = 1 THEN 1 ELSE NULL END) as PENDING_COLLECTION_COUNT, SUM(CASE WHEN cc.COLLECTION_STATUS = 1 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as PENDING_COLLECTION_AMOUNT, COUNT(CASE WHEN cc.COLLECTION_STATUS = 3 THEN 1 ELSE NULL END) as COMPLETED_COLLECTION_COUNT, SUM(CASE WHEN cc.COLLECTION_STATUS = 3 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as COMPLETED_COLLECTION_AMOUNT, COUNT(CASE WHEN cc.COLLECTION_STATUS = 4 THEN 1 ELSE NULL END) as AUDITED_COLLECTION_COUNT, SUM(CASE WHEN cc.COLLECTION_STATUS = 4 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as AUDITED_COLLECTION_AMOUNT FROM "REDACTED"."T_COST_COLLECTION" cc WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{bookId}
AND cc.TENANT_ID = #{tenantId}
AND cc.COLLECTION_PERIOD = #{period}

SELECT COUNT(1)
FROM T_COST_COLLECTION
WHERE COLLECTION_NO = #{collectionNo}

    AND COLLECTION_ID != #{collectionId}


    AND BOOK_ID = #{bookId}


    AND TENANT_ID = #{tenantId}

AND IS_DELETED = 0

SELECT
    COLLECTION_ID,
    COLLECTION_NO,
    COLLECTION_PERIOD,
    COST_CENTER_ID,
    COLLECTION_TYPE,
    COLLECTION_AMOUNT,
    COLLECTION_STATUS
FROM T_COST_COLLECTION
WHERE COLLECTION_PERIOD = #{collectionPeriod}
AND COST_CENTER_ID = #{costCenterId}

    AND COLLECTION_TYPE = #{collectionType}


    AND BOOK_ID = #{bookId}


    AND TENANT_ID = #{tenantId}

AND IS_DELETED = 0
ORDER BY CREATE_TIME DESC

SELECT cc.COST_CENTER_ID, ccc.CENTER_NAME as COST_CENTER_NAME, SUM(CASE WHEN cc.COLLECTION_TYPE = 1 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as DIRECT_COST, SUM(CASE WHEN cc.COLLECTION_TYPE = 2 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as INDIRECT_COST, SUM(CASE WHEN cc.COLLECTION_TYPE = 3 THEN cc.COLLECTION_AMOUNT ELSE 0 END) as MANUFACTURING_COST, SUM(cc.COLLECTION_AMOUNT) as TOTAL_COST, COUNT(cc.COLLECTION_ID) as COLLECTION_COUNT FROM "REDACTED"."T_COST_COLLECTION" cc LEFT JOIN "REDACTED"."T_COST_CENTER" ccc ON cc.COST_CENTER_ID = ccc.CENTER_ID WHERE cc.COLLECTION_PERIOD = #{collectionPeriod}
AND cc.BOOK_ID = #{bookId}
AND cc.TENANT_ID = #{tenantId}
AND cc.IS_DELETED = 0 GROUP BY cc.COST_CENTER_ID, ccc.CENTER_NAME ORDER BY TOTAL_COST DESC

SELECT CENTER_ID as COST_CENTER_ID, CENTER_NAME, CENTER_CODE FROM "REDACTED"."T_COST_CENTER" WHERE IS_ENABLED = 1 AND IS_DELETED = 0
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
ORDER BY CENTER_ID

SELECT COUNT(1)
FROM "REDACTED"."T_COST_CENTER"
WHERE CENTER_ID = #{costCenterId}
AND IS_ENABLED = 1
AND IS_DELETED = 0

    AND BOOK_ID = #{bookId}


    AND TENANT_ID = #{tenantId}

SELECT TO_CHAR(cc.COLLECTION_ID) AS COLLECTION_ID, cc.COLLECTION_PERIOD, ccc.CENTER_CODE, ccc.CENTER_NAME, CASE cc.COLLECTION_TYPE WHEN 1 THEN '直接成本' WHEN 2 THEN '间接成本' WHEN 3 THEN '制造费用' ELSE '未知' END AS COLLECTION_TYPE_NAME, cc.COLLECTION_AMOUNT, cc.COLLECTION_COUNT, cc.COLLECTED_AMOUNT, CASE cc.COLLECTION_STATUS WHEN 1 THEN '待归集' WHEN 2 THEN '归集中' WHEN 3 THEN '已归集' WHEN 4 THEN '已审核' ELSE '未知' END AS STATUS_NAME, u.REALNAME AS AUDITOR_NAME, cc.AUDIT_TIME, cc.REMARK, cc.CREATE_TIME, TO_CHAR(cc.BOOK_ID) AS BOOK_ID FROM "REDACTED"."T_COST_COLLECTION" cc LEFT JOIN "REDACTED"."T_COST_CENTER" ccc ON cc.COST_CENTER_ID = ccc.CENTER_ID LEFT JOIN TBL_STAFF u ON cc.AUDITOR_ID = u.STAFFID WHERE cc.COLLECTION_STATUS = 4
AND cc.COLLECTION_PERIOD = #{period}
AND cc.BOOK_ID = #{bookId}
AND cc.TENANT_ID = #{tenantId}
ORDER BY cc.CREATE_TIME DESC
